insert into public.sql_generation_rag_vectors (id, company_id, schema_name, schema_content, embedding, created_at, updated_at)
values  (1, 1, 'PRO_GIYKIMBIL.json', '{
  "view_name": "PRO_GIYKIMBIL",
  "description": "AKBS/KBS (Aile Kimlik Bilgi Sistemi / Kimlik Bilgi Sistemi) için hazırlanan misafir kimlik bilgileri listesi. Bu view, otel misafirlerinin kimlik bilgilerini, nüfus kayıt bilgilerini, konaklama detaylarını ve rezervasyon bilgilerini içerir. Hem ana misafirler (Parent) hem de eşlik eden misafirler (Acc) için bilgileri barındırır.",
  "purpose": "Bu view, otel yönetim sisteminde misafir kimlik bilgilerinin yönetimi, raporlama ve yasal gereklilikler (AKBS/KBS bildirimleri) için kullanılır. Misafirlerin kimlik doğrulama, nüfus kayıt bilgileri, konaklama tarihleri ve rezervasyon detaylarına erişim sağlar.",
  "data_types": [
    "Misafir kimlik bilgileri (TC kimlik no, ad, soyad, doğum bilgileri)",
    "Nüfus kayıt bilgileri (il, ilçe, mahalle, cilt, aile sıra, sıra numarası)",
    "Kimlik belgesi bilgileri (belge türü, seri numarası)",
    "Konaklama bilgileri (geliş tarihi, ayrılış tarihi, oda numarası)",
    "Rezervasyon bilgileri (rezervasyon tarihi, resort, misafir tipi)",
    "Kişisel bilgiler (cinsiyet, medeni hal, uyruk, ikamet adresi)",
    "Ek bilgiler (iş, araç plaka numarası)"
  ],
  "columns": [
    {
      "column_name": "SIRANO",
      "data_type": "NUMBER",
      "description": "Kayıt sıra numarası. Her kayıt için otomatik olarak ROWNUM ile atanan benzersiz sıralama numarası. Liste görünümlerinde ve raporlarda sıralama için kullanılır.",
      "nullable": false,
      "example_values": [1, 2, 3, 10, 20, 30, 48]
    },
    {
      "column_name": "PROFILE_ID",
      "data_type": "NUMBER",
      "description": "Misafir profilinin benzersiz tanımlayıcı numarası. Otel yönetim sistemindeki misafir profil kaydının ID''si. Bu ID, diğer sistemlerde ve projelerde de kullanılmaktadır. Misafir bilgilerine erişim ve profil yönetimi için anahtar alan olarak kullanılır.",
      "nullable": false,
      "example_values": [6895448, 6865372, 6900382, 217210, 3045962]
    },
    {
      "column_name": "TCKIMLIKNO",
      "data_type": "VARCHAR2",
      "description": "Türkiye Cumhuriyeti kimlik numarası. 11 haneli TC kimlik numarası. Sadece Türk vatandaşları için doldurulur, yabancı misafirler için NULL olabilir. Kimlik doğrulama ve yasal bildirimler için kritik bilgidir.",
      "nullable": true,
      "example_values": ["16658382504", "66451163428", null, "211186880"]
    },
    {
      "column_name": "SOYADI",
      "data_type": "VARCHAR2",
      "description": "Misafirin soyadı. Kişinin resmi soyadı bilgisi. Kimlik belgesindeki soyad ile eşleşmelidir.",
      "nullable": true,
      "example_values": ["KUCUK", "VEDSTED", "DALKILIC", "BAYUS", "ZAYIM"]
    },
    {
      "column_name": "ADI",
      "data_type": "VARCHAR2",
      "description": "Misafirin adı. Kişinin resmi adı bilgisi. Kimlik belgesindeki ad ile eşleşmelidir. Bazen birden fazla isim içerebilir (örn: ''SUNA ERKAYA'', ''MUAMMER ESAT'').",
      "nullable": true,
      "example_values": ["SUNA ERKAYA", "JOERGEN", "AHMET", "BERKIN", "YAGMUR"]
    },
    {
      "column_name": "BABAADI",
      "data_type": "VARCHAR2",
      "description": "Misafirin baba adı. Kişinin baba adı bilgisi. Türk nüfus kayıt sisteminde kullanılan geleneksel kimlik bilgisi. Çoğu kayıtta NULL olabilir, ancak bazı detaylı kayıtlarda doldurulmuş olabilir.",
      "nullable": true,
      "example_values": [null, "mehmet"]
    },
    {
      "column_name": "ANAADI",
      "data_type": "VARCHAR2",
      "description": "Misafirin anne adı. Kişinin anne adı bilgisi. Türk nüfus kayıt sisteminde kullanılan geleneksel kimlik bilgisi. Çoğu kayıtta NULL olabilir, ancak bazı detaylı kayıtlarda doldurulmuş olabilir.",
      "nullable": true,
      "example_values": [null, "perihan"]
    },
    {
      "column_name": "DOGUMYERI",
      "data_type": "VARCHAR2",
      "description": "Misafirin doğum yeri. Kişinin doğduğu yer bilgisi. Genellikle ülke kodu (TR, DNK, GEO, NL, TC, CYP) veya şehir adı olarak kaydedilir. Bazen ''.'' veya ''tr'' gibi kısaltmalar kullanılabilir.",
      "nullable": true,
      "example_values": ["tr", "TR", "DNK", "GE", "NL", ".", "TC"]
    },
    {
      "column_name": "DOGUMTARIHI",
      "data_type": "VARCHAR2",
      "description": "Misafirin doğum tarihi. YYYY-MM-DD formatında formatlanmış tarih bilgisi. TO_CHAR fonksiyonu ile DATE tipinden string''e dönüştürülmüştür. Kimlik doğrulama ve yaş hesaplamaları için kullanılır.",
      "nullable": true,
      "example_values": ["1976-04-29", "1975-01-17", "1995-01-01", "1983-06-12"]
    },
    {
      "column_name": "UYRUGU",
      "data_type": "VARCHAR2",
      "description": "Misafirin uyruğu (vatandaşlığı). Ülke kodu formatında kaydedilir. TC (Türkiye), DNK (Danimarka), GEO (Gürcistan), NLD (Hollanda), CYP (Kıbrıs) gibi ISO ülke kodları kullanılır. Yasal bildirimler ve istatistikler için önemlidir.",
      "nullable": true,
      "example_values": ["TC", "DNK", "GEO", "NLD", "CYP"]
    },
    {
      "column_name": "KIMLIKBELGESITURU",
      "data_type": "VARCHAR2",
      "description": "Misafirin kimlik belgesi türü. TCKN (Türkiye Cumhuriyeti Kimlik Numarası) veya P (Pasaport) değerlerini alır. Türk vatandaşları için genellikle TCKN, yabancı misafirler için P (Pasaport) kullanılır.",
      "nullable": true,
      "example_values": ["TCKN", "P"]
    },
    {
      "column_name": "KIMLIKSERINO",
      "data_type": "VARCHAR2",
      "description": "Kimlik belgesi seri numarası. TC kimlik numarası veya pasaport numarası. Türk vatandaşları için genellikle TC kimlik numarası ile aynı değer, yabancı misafirler için pasaport numarası kaydedilir.",
      "nullable": true,
      "example_values": ["16658382504", "211186880", "18AA17138", "NX59782H2", "3560025904"]
    },
    {
      "column_name": "NUFUSAKAYITLIOLDUGUIL",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu il. Türk vatandaşları için nüfus kayıt sistemindeki il bilgisi. Genellikle il kodu (TR, DK, DE, NL) veya il adı olarak kaydedilir. Yabancı misafirler için genellikle NULL olur.",
      "nullable": true,
      "example_values": [null, "TR", "DK", "DE", "NL"]
    },
    {
      "column_name": "NUFUSAKAYITLIOLDUGUILCE",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu ilçe. Türk vatandaşları için nüfus kayıt sistemindeki ilçe bilgisi. Çoğu kayıtta NULL olabilir, ancak bazı detaylı kayıtlarda ilçe adı kaydedilmiş olabilir (örn: ''merkez'').",
      "nullable": true,
      "example_values": [null, "merkez"]
    },
    {
      "column_name": "NUFUSAKAYITLIOLDUGUMAHALLE",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu mahalle. Türk vatandaşları için nüfus kayıt sistemindeki mahalle bilgisi. Çoğu kayıtta NULL olur, çok detaylı kayıtlarda doldurulmuş olabilir.",
      "nullable": true,
      "example_values": [null]
    },
    {
      "column_name": "NUFUSCILT",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu cilt numarası. Türk nüfus kayıt sistemindeki cilt numarası bilgisi. Çoğu kayıtta NULL olur, yasal bildirimler için gerekli olduğunda doldurulur.",
      "nullable": true,
      "example_values": [null]
    },
    {
      "column_name": "NUFUSAILESIRA",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu aile sıra numarası. Türk nüfus kayıt sistemindeki aile sıra numarası bilgisi. Çoğu kayıtta NULL olur, yasal bildirimler için gerekli olduğunda doldurulur.",
      "nullable": true,
      "example_values": [null]
    },
    {
      "column_name": "NUFUSSIRANO",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu sıra numarası. Türk nüfus kayıt sistemindeki sıra numarası bilgisi. Çoğu kayıtta NULL olur, yasal bildirimler için gerekli olduğunda doldurulur.",
      "nullable": true,
      "example_values": [null]
    },
    {
      "column_name": "CINSIYET",
      "data_type": "VARCHAR2",
      "description": "Misafirin cinsiyeti. E (Erkek) veya K (Kadın) değerlerini alır. Türkçe cinsiyet kodlaması kullanılır. İstatistiksel analizler ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["K", "E"]
    },
    {
      "column_name": "MEDENIHALI",
      "data_type": "VARCHAR2",
      "description": "Misafirin medeni hali. Evli, bekâr, boşanmış, dul gibi medeni durum bilgisi. Çoğu kayıtta NULL olur, detaylı profil bilgilerinde doldurulmuş olabilir.",
      "nullable": true,
      "example_values": [null]
    },
    {
      "column_name": "IKAMETADRESI",
      "data_type": "VARCHAR2",
      "description": "Misafirin ikamet adresi. Kişinin yaşadığı adres bilgisi. Genellikle şehir, ülke bilgilerini içerir. Bazen detaylı adres bilgisi de kaydedilmiş olabilir. Yasal bildirimler ve iletişim için kullanılır.",
      "nullable": true,
      "example_values": ["      Turkey", "Dk     Dk Denmark", "Istanbul Istanbul     Turkey", "Abdullah Aga Mah. Iskele Caddesi No Beylerbeyi   Uskudar    Istanbul Turkey"]
    },
    {
      "column_name": "GELISTARIHI",
      "data_type": "VARCHAR2",
      "description": "Misafirin otele geliş tarihi ve saati. YYYY-MM-DD HH24:MI:SS formatında formatlanmış tarih-saat bilgisi. TO_CHAR fonksiyonu ile DATE tipinden string''e dönüştürülmüştür. Konaklama süresi hesaplamaları ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["2026-01-10 15:51:19", "2026-01-11 23:00:00", "2026-01-12 19:34:14", "2025-12-05 15:52:00"]
    },
    {
      "column_name": "AYRILISTARIHI",
      "data_type": "VARCHAR2",
      "description": "Misafirin otelden ayrılış tarihi. YYYY-MM-DD HH24:MI:SS formatında formatlanmış tarih bilgisi. Genellikle saat bilgisi 00:00:00 olarak kaydedilir. TO_CHAR fonksiyonu ile DATE tipinden string''e dönüştürülmüştür. Konaklama süresi hesaplamaları ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["2026-01-14 00:00:00", "2026-01-13 00:00:00", "2026-01-15 00:00:00", "2026-01-23 00:00:00"]
    },
    {
      "column_name": "VERILENODANO",
      "data_type": "VARCHAR2",
      "description": "Misafire verilen oda numarası. Otel odası numarası bilgisi. Misafirin konakladığı oda numarasını gösterir. Oda yönetimi ve misafir takibi için kullanılır.",
      "nullable": true,
      "example_values": ["209", "409", "112", "406", "404", "106", "605", "303"]
    },
    {
      "column_name": "ISI",
      "data_type": "VARCHAR2",
      "description": "Misafirin iş/meslek bilgisi. Kişinin çalıştığı iş veya meslek bilgisi. Çoğu kayıtta NULL olur, detaylı profil bilgilerinde doldurulmuş olabilir.",
      "nullable": true,
      "example_values": [null]
    },
    {
      "column_name": "ARACPLAKANO",
      "data_type": "VARCHAR2",
      "description": "Misafirin araç plaka numarası. Otelde konaklayan misafirin getirdiği araç plaka numarası. Otopark yönetimi ve güvenlik kayıtları için kullanılır. Çoğu kayıtta NULL olur.",
      "nullable": true,
      "example_values": [null]
    },
    {
      "column_name": "RESORT",
      "data_type": "VARCHAR2",
      "description": "Misafirin konakladığı resort/otel kodu. Otel zincirindeki belirli bir otel veya resort''u tanımlayan kod. Örnek: ISTAL (Istanbul Altunizade). Rezervasyon ve gelir yönetimi için kullanılır.",
      "nullable": true,
      "example_values": ["ISTAL"]
    },
    {
      "column_name": "RESERVATION_DATE",
      "data_type": "VARCHAR2",
      "description": "Rezervasyon tarihi. Misafirin rezervasyonunun yapıldığı veya geçerli olduğu tarih. YYYY-MM-DD formatında kaydedilir. Rezervasyon yönetimi ve analizi için kullanılır.",
      "nullable": true,
      "example_values": ["2026-01-13"]
    },
    {
      "column_name": "TIP",
      "data_type": "VARCHAR2",
      "description": "Misafir tipi. Misafirin rezervasyondaki rolünü belirtir. ''Parent    '' (Ana misafir - rezervasyonu yapan veya ana konaklayan) veya ''Acc       '' (Accompanying - eşlik eden misafir, ana misafirle birlikte konaklayan) değerlerini alır. Rezervasyon yapısını ve fatura düzenlemesini anlamak için önemlidir.",
      "nullable": true,
      "example_values": ["Parent    ", "Acc       "]
    }
  ],
  "usage_scenarios": [
    "AKBS/KBS yasal bildirimleri için misafir kimlik bilgilerinin hazırlanması",
    "Misafir kimlik doğrulama ve profil yönetimi",
    "Nüfus kayıt bilgilerine dayalı raporlama",
    "Konaklama tarihleri ve süreleri analizi",
    "Rezervasyon ve misafir tipi bazlı istatistikler",
    "Yabancı ve yerli misafir ayrımı ve analizi",
    "Oda bazlı misafir takibi",
    "Cinsiyet, yaş ve uyruk bazlı demografik analizler"
  ],
  "source_information": "Bu view, ppgiykimbil.akbs fonksiyonundan gelen verileri birleştirir. Fonksiyon hem ''N'' (yeni) hem de ''Y'' (eski) parametreleriyle çağrılarak UNION ALL ile birleştirilir."
}
