        (2, 1, 'PRO_GIYKIMBIL_REPORT.json', '{
  "view_name": "PRO_GIYKIMBIL_REPORT",
  "description": "AKBS/KBS (Aile Kimlik Bilgi Sistemi / Kimlik Bilgi Sistemi) raporlama için hazırlanan misafir kimlik bilgileri view''ı. Bu view, rezervasyon günlük verilerinden (reservation_daily_elements) ana misafirlerin (Parent) kimlik bilgilerini çeker ve her konaklama günü için ayrı kayıt oluşturur. Sadece CHECKED IN ve CHECKED OUT durumundaki rezervasyonları içerir. Farklı otel zincirleri (KEMPINSKI, FAIRMONT, DEDEMAN) ve resort''lar (ISTAN, ISTPH, IST, BOP) için özelleştirilmiş alan eşleştirmeleri yapar.",
  "purpose": "Bu view, otel yönetim sisteminde günlük bazlı misafir kimlik bilgileri raporlaması için kullanılır. AKBS/KBS yasal bildirimleri, günlük misafir takibi, rezervasyon durumu bazlı raporlama ve farklı otel zincirleri için uyumlu veri sağlama amacıyla kullanılır. Her konaklama günü için ayrı kayıt oluşturarak günlük bazlı analiz imkanı sunar.",
  "data_types": [
    "Misafir kimlik bilgileri (profil ID, TC kimlik no, ad, soyad, baba adı, anne adı, doğum bilgileri)",
    "Nüfus kayıt bilgileri (il, ilçe - diğer nüfus alanları boş string olarak döner)",
    "Kimlik belgesi bilgileri (belge türü, seri numarası)",
    "Konaklama bilgileri (geliş tarihi, ayrılış tarihi, oda numarası, rezervasyon tarihi)",
    "Rezervasyon durumu bilgileri (rezervasyon durumu, başlangıç tarihi, bitiş tarihi)",
    "Kişisel bilgiler (cinsiyet, uyruk, ikamet adresi)",
    "Otel bilgileri (resort kodu, misafir tipi)"
  ],
  "columns": [
    {
      "column_name": "PROFILE_ID",
      "data_type": "NUMBER",
      "description": "Misafir profilinin benzersiz tanımlayıcı numarası. name tablosundaki name_id değeridir. Otel yönetim sistemindeki misafir profil kaydının ID''si. Diğer sistemlerde ve projelerde de kullanılmaktadır. Misafir bilgilerine erişim ve profil yönetimi için anahtar alan olarak kullanılır.",
      "nullable": false,
      "example_values": [12460, 6895448, 6865372]
    },
    {
      "column_name": "TCKIMLIKNO",
      "data_type": "VARCHAR2",
      "description": "Türkiye Cumhuriyeti kimlik numarası. Resort ve otel zincirine göre farklı alanlardan alınır: ISTAN/ISTPH için udfc17, KEMPINSKI için udfn01, diğerleri için udfn30. 11 haneli TC kimlik numarası veya NULL. Sadece Türk vatandaşları için doldurulur, yabancı misafirler için NULL olabilir. Kimlik doğrulama ve yasal bildirimler için kritik bilgidir.",
      "nullable": true,
      "example_values": [null, "16658382504", "66451163428"]
    },
    {
      "column_name": "SOYADI",
      "data_type": "VARCHAR2",
      "description": "Misafirin soyadı. name tablosundaki sname alanından alınır. Kişinin resmi soyadı bilgisi. Kimlik belgesindeki soyad ile eşleşmelidir.",
      "nullable": true,
      "example_values": ["SYED IRFAN", "KUCUK", "VEDSTED", "DALKILIC"]
    },
    {
      "column_name": "ADI",
      "data_type": "VARCHAR2",
      "description": "Misafirin adı. name tablosundaki sfirst alanından alınır. Kişinin resmi adı bilgisi. Kimlik belgesindeki ad ile eşleşmelidir.",
      "nullable": true,
      "example_values": ["ALI", "SUNA ERKAYA", "JOERGEN", "AHMET"]
    },
    {
      "column_name": "BABAADI",
      "data_type": "VARCHAR2",
      "description": "Misafirin baba adı. Resort ve otel zincirine göre farklı alanlardan alınır: ISTAN/ISTPH için udfc18, KEMPINSKI için udfc01, FAIRMONT için udfc37, diğerleri için udfc22. Kişinin baba adı bilgisi. Türk nüfus kayıt sisteminde kullanılan geleneksel kimlik bilgisi. Çoğu kayıtta NULL olabilir.",
      "nullable": true,
      "example_values": [null, "mehmet"]
    },
    {
      "column_name": "ANAADI",
      "data_type": "VARCHAR2",
      "description": "Misafirin anne adı. Resort ve otel zincirine göre farklı alanlardan alınır: ISTAN/ISTPH/IST/BOP için udfc19, KEMPINSKI için udfc02, FAIRMONT için udfc38, DEDEMAN için udfc33, diğerleri için udfc23. Kişinin anne adı bilgisi. Türk nüfus kayıt sisteminde kullanılan geleneksel kimlik bilgisi. Çoğu kayıtta NULL olabilir.",
      "nullable": true,
      "example_values": [null, "perihan"]
    },
    {
      "column_name": "DOGUMYERI",
      "data_type": "VARCHAR2",
      "description": "Misafirin doğum yeri. Bu view''da her zaman boş string ('''') olarak döner. Doğum yeri bilgisi bu view''da tutulmamaktadır.",
      "nullable": true,
      "example_values": [""]
    },
    {
      "column_name": "DOGUMTARIHI",
      "data_type": "DATE",
      "description": "Misafirin doğum tarihi. name tablosundaki birth_date alanından alınır. DATE tipinde kaydedilir. Kimlik doğrulama ve yaş hesaplamaları için kullanılır.",
      "nullable": true,
      "example_values": [null, "1976-04-29", "1975-01-17"]
    },
    {
      "column_name": "UYRUGU",
      "data_type": "VARCHAR2",
      "description": "Misafirin uyruğu (vatandaşlığı). name tablosundaki nationality alanından pro_country_nation_link tablosu üzerinden nation_code olarak çekilir. Ülke kodu formatında kaydedilir (PAK, TC, DNK, GEO, NLD, CYP gibi). Yasal bildirimler ve istatistikler için önemlidir.",
      "nullable": true,
      "example_values": ["PAK", "TC", "DNK", "GEO", "NLD", "CYP"]
    },
    {
      "column_name": "KIMLIKBELGESITURU",
      "data_type": "VARCHAR2",
      "description": "Misafirin kimlik belgesi türü. name tablosundaki id_type alanından alınır, ancak KEMPINSKI için özel dönüşüm yapılır: ''I'' -> ''N'', ''D'' -> ''E''. Genellikle TCKN, P (Pasaport), N, E gibi değerler alır. Türk vatandaşları için genellikle TCKN, yabancı misafirler için P (Pasaport) kullanılır.",
      "nullable": true,
      "example_values": [null, "TCKN", "P", "N", "E"]
    },
    {
      "column_name": "KIMLIKSERINO",
      "data_type": "VARCHAR2",
      "description": "Kimlik belgesi seri numarası. KEMPINSKI için passport alanından, diğerleri için id_number alanından alınır. TC kimlik numarası veya pasaport numarası. Türk vatandaşları için genellikle TC kimlik numarası ile aynı değer, yabancı misafirler için pasaport numarası kaydedilir.",
      "nullable": true,
      "example_values": [null, "16658382504", "211186880", "18AA17138"]
    },
    {
      "column_name": "NUFUSAKAYITLIOLDUGUIL",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu il. Resort ve otel zincirine göre farklı alanlardan alınır: ISTAN/ISTPH için id_place, IST/BOP için udfc26, KEMPINSKI için udfc03, DEDEMAN için udfc36, FAIRMONT için udfc39, diğerleri için udfc30. Genellikle il kodu veya il adı olarak kaydedilir. Yabancı misafirler için genellikle NULL olur.",
      "nullable": true,
      "example_values": [null, "TR", "DK", "DE"]
    },
    {
      "column_name": "NUFUSAKAYITLIOLDUGUILCE",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu ilçe. Resort ve otel zincirine göre farklı alanlardan alınır: ISTAN/ISTPH için udfc20, IST/BOP için udfc27, KEMPINSKI için udfc08, DEDEMAN için udfc37, FAIRMONT için udfc05, diğerleri için udfc31. Türk vatandaşları için nüfus kayıt sistemindeki ilçe bilgisi. Çoğu kayıtta NULL olabilir.",
      "nullable": true,
      "example_values": [null, "merkez"]
    },
    {
      "column_name": "NUFUSAKAYITLIOLDUGUMAHALLE",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu mahalle. Bu view''da her zaman boş string ('''') olarak döner. Mahalle bilgisi bu view''da tutulmamaktadır.",
      "nullable": true,
      "example_values": [""]
    },
    {
      "column_name": "NUFUSCILT",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu cilt numarası. Bu view''da her zaman boş string ('''') olarak döner. Cilt numarası bilgisi bu view''da tutulmamaktadır.",
      "nullable": true,
      "example_values": [""]
    },
    {
      "column_name": "NUFUSAILESIRA",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu aile sıra numarası. Bu view''da her zaman boş string ('''') olarak döner. Aile sıra numarası bilgisi bu view''da tutulmamaktadır.",
      "nullable": true,
      "example_values": [""]
    },
    {
      "column_name": "NUFUSSIRANO",
      "data_type": "VARCHAR2",
      "description": "Misafirin nüfusa kayıtlı olduğu sıra numarası. Bu view''da her zaman boş string ('''') olarak döner. Sıra numarası bilgisi bu view''da tutulmamaktadır.",
      "nullable": true,
      "example_values": [""]
    },
    {
      "column_name": "CINSIYET",
      "data_type": "VARCHAR2",
      "description": "Misafirin cinsiyeti. name tablosundaki gender alanından DECODE fonksiyonu ile dönüştürülür: ''M'' -> ''E'' (Erkek), ''F'' -> ''K'' (Kadın), NULL -> NULL. Türkçe cinsiyet kodlaması kullanılır. İstatistiksel analizler ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["K", "E", null]
    },
    {
      "column_name": "MEDENIHALI",
      "data_type": "VARCHAR2",
      "description": "Misafirin medeni hali. Bu view''da her zaman boş string ('''') olarak döner. Medeni hal bilgisi bu view''da tutulmamaktadır.",
      "nullable": true,
      "example_values": [""]
    },
    {
      "column_name": "IKAMETADRESI",
      "data_type": "VARCHAR2",
      "description": "Misafirin ikamet adresi. name_address tablosundan primary_yn = ''Y'' olan kayıttan birleştirilerek oluşturulur. address1, address2, address3, address4, zip_code, city, state ve country bilgileri birleştirilerek tam adres oluşturulur. State bilgisi country_states tablosundan, country bilgisi country$ tablosundan çekilir. Yasal bildirimler ve iletişim için kullanılır.",
      "nullable": true,
      "example_values": ["     Pakistan Pakistan", "      Turkey", "Istanbul Istanbul     Turkey"]
    },
    {
      "column_name": "GELISTARIHI",
      "data_type": "DATE",
      "description": "Misafirin otele geliş tarihi ve saati. reservation_name tablosundaki begin_date alanından alınır. DATE tipinde kaydedilir. Konaklama süresi hesaplamaları ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["2011-08-01 16:02:00", "2026-01-10 15:51:19", "2026-01-11 23:00:00"]
    },
    {
      "column_name": "AYRILISTARIHI",
      "data_type": "DATE",
      "description": "Misafirin otelden ayrılış tarihi. reservation_name tablosundaki end_date alanından alınır. DATE tipinde kaydedilir. Konaklama süresi hesaplamaları ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["2011-08-04 18:15:00", "2026-01-14 00:00:00", "2026-01-13 00:00:00"]
    },
    {
      "column_name": "VERILENODANO",
      "data_type": "VARCHAR2",
      "description": "Misafire verilen oda numarası. reservation_daily_elements tablosundaki room alanından alınır. Otel odası numarası bilgisi. Misafirin konakladığı oda numarasını gösterir. Oda yönetimi ve misafir takibi için kullanılır.",
      "nullable": true,
      "example_values": ["404", "209", "409", "112", "406"]
    },
    {
      "column_name": "ISI",
      "data_type": "VARCHAR2",
      "description": "Misafirin iş/meslek bilgisi. Bu view''da her zaman boş string ('''') olarak döner. İş bilgisi bu view''da tutulmamaktadır.",
      "nullable": true,
      "example_values": [""]
    },
    {
      "column_name": "ARACPLAKANO",
      "data_type": "VARCHAR2",
      "description": "Misafirin araç plaka numarası. Bu view''da her zaman boş string ('''') olarak döner. Araç plaka bilgisi bu view''da tutulmamaktadır.",
      "nullable": true,
      "example_values": [""]
    },
    {
      "column_name": "RESERVATION_DATE",
      "data_type": "DATE",
      "description": "Rezervasyon günü tarihi. reservation_daily_elements tablosundaki reservation_date alanından alınır. Her konaklama günü için ayrı kayıt oluşturulduğu için, aynı misafir için birden fazla kayıt olabilir (her gün için bir kayıt). Rezervasyon yönetimi ve günlük bazlı analiz için kullanılır.",
      "nullable": true,
      "example_values": ["2011-08-01", "2011-08-02", "2011-08-03", "2026-01-13"]
    },
    {
      "column_name": "RESV_STATUS",
      "data_type": "VARCHAR2",
      "description": "Rezervasyon durumu. reservation_name tablosundaki resv_status alanından alınır. Bu view sadece ''CHECKED IN'' (giriş yapılmış) ve ''CHECKED OUT'' (çıkış yapılmış) durumundaki rezervasyonları içerir. Rezervasyon takibi ve durum bazlı raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["CHECKED IN", "CHECKED OUT"]
    },
    {
      "column_name": "TIP",
      "data_type": "VARCHAR2",
      "description": "Misafir tipi. Bu view''da her zaman ''Parent'' (Ana misafir) değerini alır. Bu view sadece ana misafirleri (rezervasyonu yapan veya ana konaklayan) gösterir, eşlik eden misafirler (Accompanying) bu view''da yer almaz. Rezervasyon yapısını anlamak için önemlidir.",
      "nullable": false,
      "example_values": ["Parent"]
    },
    {
      "column_name": "RESORT",
      "data_type": "VARCHAR2",
      "description": "Misafirin konakladığı resort/otel kodu. reservation_daily_elements tablosundaki resort alanından alınır (performans nedeniyle reservation_name.resort yerine kullanılmıştır). Otel zincirindeki belirli bir otel veya resort''u tanımlayan kod. Örnek: ISTAL (Istanbul Altunizade), ISTAN, ISTPH, IST, BOP. Rezervasyon ve gelir yönetimi için kullanılır.",
      "nullable": true,
      "example_values": ["ISTAL", "ISTAN", "ISTPH", "IST", "BOP"]
    },
    {
      "column_name": "BEGIN_DATE",
      "data_type": "DATE",
      "description": "Rezervasyon başlangıç tarihi (tarih kısmı, saat bilgisi olmadan). reservation_name tablosundaki trunc_begin_date alanından alınır. Rezervasyonun başladığı günü gösterir. Tarih aralığı filtreleme ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["2011-08-01", "2026-01-10", "2026-01-11"]
    },
    {
      "column_name": "END_DATE",
      "data_type": "DATE",
      "description": "Rezervasyon bitiş tarihi (tarih kısmı, saat bilgisi olmadan). reservation_name tablosundaki trunc_end_date alanından alınır. Rezervasyonun bittiği günü gösterir. Tarih aralığı filtreleme ve raporlama için kullanılır. Day-use (günlük kullanım) rezervasyonlarında begin_date ile end_date aynı olabilir.",
      "nullable": true,
      "example_values": ["2011-08-04", "2026-01-14", "2026-01-13"]
    }
  ],
  "usage_scenarios": [
    "AKBS/KBS yasal bildirimleri için günlük bazlı misafir kimlik bilgilerinin hazırlanması",
    "Günlük bazlı misafir takibi ve raporlama",
    "Rezervasyon durumu bazlı (CHECKED IN, CHECKED OUT) analizler",
    "Ana misafir (Parent) bazlı kimlik bilgileri raporlaması",
    "Farklı otel zincirleri (KEMPINSKI, FAIRMONT, DEDEMAN) için uyumlu veri sağlama",
    "Farklı resort''lar (ISTAN, ISTPH, IST, BOP) için özelleştirilmiş alan eşleştirmeleri",
    "Konaklama günü bazlı detaylı analizler",
    "Yabancı ve yerli misafir ayrımı ve analizi",
    "Oda bazlı misafir takibi",
    "Cinsiyet, yaş ve uyruk bazlı demografik analizler"
  ],
  "source_information": "Bu view, reservation_name, name, reservation_daily_elements ve reservation_daily_element_name tablolarından veri çeker. Sadece CHECKED IN ve CHECKED OUT durumundaki rezervasyonları içerir. room_category ''-'' ile başlamayan kayıtları filtreler. CHECKED OUT rezervasyonlarının son günü hariç tutulur (e.reservation_date != rn.trunc_end_date koşulu ile), ancak day-use rezervasyonları (trunc_begin_date = trunc_end_date) dahil edilir. Her konaklama günü için ayrı kayıt oluşturulur."
}
