  "metric_definitions": {
    "TOTAL_ROOMS": "Toplam fiziksel oda sayısı. inventory_statistics.get_physical_rooms fonksiyonu ile hesaplanır. Otelin toplam oda kapasitesini gösterir.",
    "OUT_OF_ORDER": "Kullanılamaz oda sayısı. ctr_panel_pkg.oorooms fonksiyonu ile hesaplanır. Bakım, onarım veya diğer nedenlerle kullanılamayan oda sayısı.",
    "INVENTORY_ROOMS": "Envanter oda sayısı. TOTAL_ROOMS - OUT_OF_ORDER formülü ile hesaplanır. Kullanılabilir toplam oda sayısı.",
    "DEDUCTED_BLKROOM_NPU": "Kesin blok oda sayısı (pick-up olmayan). pms_grgrid.allotment_definite_rooms fonksiyonu ile hesaplanır. Kesin blok rezervasyonlardan pick-up olmayan oda sayısı.",
    "DEDUCTED_BLKROOM_PU": "Kesin blok oda sayısı (pick-up olan). definite_block_room değeridir. Kesin blok rezervasyonlardan pick-up olan oda sayısı.",
    "TOTAL_DEDUCT_ROOMS": "Toplam kesin blok oda sayısı. DEDUCTED_BLKROOM_NPU + definite_room formülü ile hesaplanır. Kesin blok rezervasyonların toplam oda sayısı.",
    "NDEDUCTED_BLKROOM_NPU": "Geçici blok oda sayısı (pick-up olmayan). pms_grgrid.allotment_tentative_rooms fonksiyonu ile hesaplanır. Geçici blok rezervasyonlardan pick-up olmayan oda sayısı.",
    "NDEDUCTED_BLKROOM_PU": "Geçici blok oda sayısı (pick-up olan). tentative_block_room değeridir. Geçici blok rezervasyonlardan pick-up olan oda sayısı.",
    "TOTAL_NDEDUCT_ROOMS": "Toplam geçici blok oda sayısı. NDEDUCTED_BLKROOM_NPU + NDEDUCTED_BLKROOM_PU formülü ile hesaplanır. Geçici blok rezervasyonların toplam oda sayısı.",
    "MAX_AVAILABILITY": "Maksimum müsaitlik. (INVENTORY_ROOMS) - (DEDUCTED_BLKROOM_NPU + definite_room) formülü ile hesaplanır. Maksimum müsait oda sayısı.",
    "MIN_AVAILABILITY": "Minimum müsaitlik. (INVENTORY_ROOMS) - (TOTAL_NDEDUCT_ROOMS + TOTAL_DEDUCT_ROOMS) formülü ile hesaplanır. Minimum müsait oda sayısı (geçici bloklar dahil).",
    "MINOCC": "Minimum doluluk oranı (yüzde). 100 * (TOTAL_NDEDUCT_ROOMS + TOTAL_DEDUCT_ROOMS) / INVENTORY_ROOMS formülü ile hesaplanır. Geçici ve kesin bloklar dahil minimum doluluk yüzdesi.",
    "MAXOCC": "Maksimum doluluk oranı (yüzde). 100 * (TOTAL_DEDUCT_ROOMS) / INVENTORY_ROOMS formülü ile hesaplanır. Sadece kesin bloklar dahil maksimum doluluk yüzdesi.",
    "TOTAL_ROOMS_RESERVED": "Toplam rezerve edilmiş oda sayısı. definite_room + tentative_room formülü ile hesaplanır. Kesin ve geçici rezervasyonların toplam oda sayısı.",
    "ADULT_IN_HOUSE": "Evdeki yetişkin sayısı. reservation_summary tablosundan resv_inv_type = ''D'' olan kayıtların adults toplamı.",
    "CHILDREN_IN_HOUSE": "Evdeki çocuk sayısı. reservation_summary tablosundan resv_inv_type = ''D'' olan kayıtların children toplamı.",
    "ARRIVAL_ROOM": "Geliş oda sayısı. reservation_summary tablosundan arr_rooms toplamı. Belirli bir günde geliş yapan rezervasyonların oda sayısı.",
    "ARRIVAL_PERSON": "Geliş kişi sayısı. reservation_summary tablosundan arr_persons toplamı. Belirli bir günde geliş yapan rezervasyonların kişi sayısı.",
    "DEPARTURE_ROOM": "Ayrılış oda sayısı. reservation_summary tablosundan resv_inv_type IN (''D'', ''C'', ''T'') olan kayıtların dep_rooms toplamı. Belirli bir günde ayrılış yapan rezervasyonların oda sayısı.",
    "DEPARTURE_PERSON": "Ayrılış kişi sayısı. reservation_summary tablosundan resv_inv_type IN (''D'', ''C'', ''T'') olan kayıtların dep_persons toplamı. Belirli bir günde ayrılış yapan rezervasyonların kişi sayısı.",
    "DAYUSE_ROOM": "Günlük kullanım oda sayısı. reservation_summary tablosundan day_use_rooms toplamı. Belirli bir günde günlük kullanım (day-use) yapan rezervasyonların oda sayısı.",
    "DAYUSE_PERSON": "Günlük kullanım kişi sayısı. reservation_summary tablosundan day_use_persons toplamı. Belirli bir günde günlük kullanım (day-use) yapan rezervasyonların kişi sayısı."
  },
  "usage_scenarios": [
    "Otel kontrol paneli ve dashboard görünümleri",
    "Aylık günlük bazlı oda envanteri takibi",
    "Rezervasyon planlaması ve kapasite yönetimi",
    "Doluluk oranı analizi ve tahminleme",
    "Geliş/ayrılış takibi ve operasyonel planlama",
    "Blok oda yönetimi ve analizi",
    "Günlük kullanım (day-use) analizi",
    "Müsaitlik hesaplamaları ve fiyatlandırma kararları",
    "Yönetici raporları ve performans takibi"
  ],
  "source_information": "Bu view, reservation_summary tablosundan veri çeker. considered_date BETWEEN TRUNC(ppf.bdate(resort), ''MM'') AND LAST_DAY(ppf.bdate(resort)) koşulu ile ayın tüm günleri için veri toplar. event_type = ''R'' ve psuedo_room_yn = ''N'' filtreleri uygulanır. Her metrik türü (line_no 1-22) için number_scale tablosu ile cross join yapılarak 22 satır oluşturulur. Her gün (1-31) için CASE WHEN yapıları ile ilgili metrik değerleri toplanır ve BD1-BD31 sütunlarına yerleştirilir."
}
