        (6, 1, 'PV_ISV_FIN_FOLIOS.json', '{
  "view_name": "PV_ISV_FIN_FOLIOS",
  "description": "Finansal folyo (folio) bilgileri view''ı. Bu view, otel misafirlerinin finansal işlemlerini, fatura bilgilerini, ödeme detaylarını ve vergi bilgilerini içerir. financial_transactions_view, name ve reservation_name tablolarından veri çekerek her misafir için fatura bazlı finansal özet bilgileri sağlar. Net ve gross gelir hesaplamaları, ödeme yapan kişi bilgileri, vergi numarası ve fatura durumu gibi kritik finansal bilgileri barındırır.",
  "purpose": "Bu view, otel yönetim sisteminde finansal raporlama, fatura yönetimi, vergi bildirimleri, gelir analizi ve muhasebe işlemleri için kullanılır. Misafir bazlı finansal özetler, ödeme yapan kişi bilgileri, fatura durumu takibi ve vergi bilgilerine erişim sağlar. Muhasebe ve finans ekipleri tarafından fatura oluşturma, ödeme takibi ve vergi raporlaması için kullanılır.",
  "data_types": [
    "Misafir bilgileri (name_id, name_type, last_name, first_name, company_name, membership_card_no)",
    "Ödeme yapan kişi bilgileri (payee_name_id, payee_name, payee_membership_card_no)",
    "İletişim kişisi bilgileri (resv_contact_id, contact_last_name, contact_first_name, contact_membership_card_no)",
    "Fatura bilgileri (bill_no, folio_no, fiscal_bill_no, bill_generation_date, status, bill_payment_trx_no, bill_count)",
    "Konaklama bilgileri (room, arrival, departure, country)",
    "Vergi bilgileri (citizen_number, tax_no, tax_office)",
    "Finansal bilgiler (net, gross, ar_no)"
  ],
  "columns": [
    {
      "column_name": "RESORT",
      "data_type": "VARCHAR2",
      "description": "Resort/otel kodu. financial_transactions_view tablosundan alınır. Otel zincirindeki belirli bir otel veya resort''u tanımlayan kod. Örnek: ISTAL (Istanbul Altunizade). Rezervasyon ve gelir yönetimi için kullanılır.",
      "nullable": true,
      "example_values": ["ISTAL", "ISTAN", "ISTPH", "IST", "BOP"]
    },
    {
      "column_name": "NAME_ID",
      "data_type": "NUMBER",
      "description": "Misafir profilinin benzersiz tanımlayıcı numarası. financial_transactions_view tablosundan alınır. Otel yönetim sistemindeki misafir profil kaydının ID''si. Misafir bilgilerine erişim ve profil yönetimi için anahtar alan olarak kullanılır.",
      "nullable": true,
      "example_values": [334500, 591500, 6460000]
    },
    {
      "column_name": "NAME_TYPE",
      "data_type": "VARCHAR2",
      "description": "Misafir tipi. name tablosundaki name_type alanından dönüştürülür: ''D'' -> ''INDIVIDUAL'' (Bireysel), ''G'' -> ''GROUP'' (Grup), ''S'' -> ''SOURCE'' (Kaynak), diğerleri olduğu gibi kalır. Misafirin bireysel, grup veya kaynak olup olmadığını belirtir. Vergi ve fatura işlemleri için önemlidir.",
      "nullable": true,
      "example_values": ["INDIVIDUAL", "GROUP", "SOURCE"]
    },
    {
      "column_name": "LAST_NAME",
      "data_type": "VARCHAR2",
      "description": "Misafirin soyadı. name tablosundaki LAST alanından alınır. Kişinin resmi soyadı bilgisi. Fatura ve vergi bildirimleri için kullanılır.",
      "nullable": true,
      "example_values": ["Babah", "Sonmez", "Guven"]
    },
    {
      "column_name": "FIRST_NAME",
      "data_type": "VARCHAR2",
      "description": "Misafirin adı. name tablosundaki FIRST alanından alınır. Kişinin resmi adı bilgisi. Fatura ve vergi bildirimleri için kullanılır.",
      "nullable": true,
      "example_values": ["Mustapha", "Hulya", "Eyup"]
    },
    {
      "column_name": "COMPANY_NAME",
      "data_type": "VARCHAR2",
      "description": "Şirket adı. name tablosundaki company alanından alınır. Kurumsal misafirler için şirket adı bilgisi. Bireysel misafirler için genellikle NULL olur. Kurumsal faturalama için kullanılır.",
      "nullable": true,
      "example_values": [null, "Tatil Budur Seyahat Acente ve TuR AS"]
    },
    {
      "column_name": "MEMBERSHIP_CARD_NO",
      "data_type": "VARCHAR2",
      "description": "Misafirin üyelik kartı numarası. ppf.membership_card_no(ft.resort, ft.name_id) fonksiyonu ile hesaplanır. Misafirin sadakat programı üyelik kartı numarası. İndirim ve özel fiyatlandırma için kullanılır.",
      "nullable": true,
      "example_values": [null, "1234567890"]
    },
    {
      "column_name": "PAYEE_NAME_ID",
      "data_type": "NUMBER",
      "description": "Ödeme yapan kişinin profil ID''si. folio$_tax tablosundan payee_name_id alanından alınır (ROWNUM = 1 ile ilk kayıt). Faturayı ödeyen kişinin profil ID''si. Misafir kendisi ödüyorsa name_id ile aynı, başka biri ödüyorsa farklı olabilir.",
      "nullable": true,
      "example_values": [334500, 844463, 6460000]
    },
    {
      "column_name": "PAYEE_NAME",
      "data_type": "VARCHAR2",
      "description": "Ödeme yapan kişinin adı. reservation_ref.get_name(payee_name_id) fonksiyonu ile hesaplanır. Faturayı ödeyen kişinin adı. Fatura ve ödeme takibi için kullanılır.",
      "nullable": true,
      "example_values": ["Babah", "Tatil Budur Seyahat Acente ve TuR AS", "Guven"]
    },
    {
      "column_name": "PAYEE_MEMBERSHIP_CARD_NO",
      "data_type": "VARCHAR2",
      "description": "Ödeme yapan kişinin üyelik kartı numarası. ppf.membership_card_no(resort, payee_name_id) fonksiyonu ile hesaplanır. Faturayı ödeyen kişinin sadakat programı üyelik kartı numarası.",
      "nullable": true,
      "example_values": [null, "1234567890"]
    },
    {
      "column_name": "RESV_CONTACT_ID",
      "data_type": "NUMBER",
      "description": "Rezervasyon iletişim kişisinin profil ID''si. reservation_name tablosundaki resv_contact_id alanından alınır. Rezervasyonla ilgili iletişim kurulacak kişinin profil ID''si. Genellikle kurumsal rezervasyonlarda farklı bir kişi olabilir.",
      "nullable": true,
      "example_values": [null, 123456]
    },
    {
      "column_name": "CONTACT_LAST_NAME",
      "data_type": "VARCHAR2",
      "description": "İletişim kişisinin soyadı. name tablosundan resv_contact_id ile eşleştirilerek LAST alanından alınır. Rezervasyonla ilgili iletişim kurulacak kişinin soyadı.",
      "nullable": true,
      "example_values": [null, "Doe", "Smith"]
    },
    {
      "column_name": "CONTACT_FIRST_NAME",
      "data_type": "VARCHAR2",
      "description": "İletişim kişisinin adı. name tablosundan resv_contact_id ile eşleştirilerek FIRST alanından alınır. Rezervasyonla ilgili iletişim kurulacak kişinin adı.",
      "nullable": true,
      "example_values": [null, "John", "Jane"]
    },
    {
      "column_name": "CONTACT_MEMBERSHIP_CARD_NO",
      "data_type": "VARCHAR2",
      "description": "İletişim kişisinin üyelik kartı numarası. ppf.membership_card_no(ft.resort, rn.resv_contact_id) fonksiyonu ile hesaplanır. Rezervasyonla ilgili iletişim kurulacak kişinin sadakat programı üyelik kartı numarası.",
      "nullable": true,
      "example_values": [null, "1234567890"]
    },
    {
      "column_name": "BILL_GENERATION_DATE",
      "data_type": "DATE",
      "description": "Fatura oluşturulma tarihi. folio$_tax tablosundan bill_generation_date alanından alınır (ROWNUM = 1 ile ilk kayıt). Faturanın oluşturulduğu tarih. Muhasebe ve vergi raporlaması için kullanılır.",
      "nullable": true,
      "example_values": ["2012-02-14", "2016-05-08", "2019-02-25"]
    },
    {
      "column_name": "BILL_NO",
      "data_type": "NUMBER",
      "description": "Fatura numarası. financial_transactions_view tablosundaki bill_no alanından alınır. Faturanın benzersiz numarası. Fatura takibi ve referans için kullanılır. bill_no IS NOT NULL koşulu ile filtrelenir.",
      "nullable": false,
      "example_values": [1680, 28523, 51182]
    },
    {
      "column_name": "FOLIO_NO",
      "data_type": "NUMBER",
      "description": "Folyo numarası. financial_transactions_view tablosundaki folio_no alanından alınır. Misafirin konaklama süresince tutulan folyo (hesap) numarası. Folyo yönetimi ve hesap takibi için kullanılır.",
      "nullable": true,
      "example_values": [418171, 6684391, 9141692]
    },
    {
      "column_name": "FISCAL_BILL_NO",
      "data_type": "VARCHAR2",
      "description": "Mali fatura numarası. financial_transactions_view tablosundaki fiscal_bill_no alanından alınır. Vergi dairesi için mali fatura numarası. Vergi bildirimleri ve muhasebe işlemleri için kullanılır. Genellikle NULL olabilir.",
      "nullable": true,
      "example_values": [null, "10330", "59847"]
    },
    {
      "column_name": "STATUS",
      "data_type": "VARCHAR2",
      "description": "Fatura durumu. folio$_tax tablosundan status alanından alınır (ROWNUM = 1 ile ilk kayıt). Faturanın durumunu gösterir. Örnek: ''OK'' (Tamamlanmış), ''PENDING'' (Beklemede), ''CANCELLED'' (İptal edilmiş). Fatura durumu takibi için kullanılır.",
      "nullable": true,
      "example_values": ["OK", "PENDING", "CANCELLED"]
    },
    {
      "column_name": "ROOM",
      "data_type": "VARCHAR2",
      "description": "Oda numarası. financial_transactions_view tablosundaki room alanından alınır. Misafirin konakladığı oda numarası. Oda bazlı gelir analizi için kullanılır.",
      "nullable": true,
      "example_values": ["103", "303", "111"]
    },
    {
      "column_name": "COUNTRY",
      "data_type": "VARCHAR2",
      "description": "Misafirin ülkesi. name_address tablosundan primary_yn = ''Y'' olan kayıttan country alanından alınır. Misafirin ikamet ettiği ülke kodu. Örnek: ''FR'' (Fransa), ''TR'' (Türkiye). Vergi ve istatistik raporlaması için kullanılır.",
      "nullable": true,
      "example_values": ["FR", "TR", "US", "DE"]
    },
    {
      "column_name": "BILL_COUNT",
      "data_type": "NUMBER",
      "description": "Fatura sayısı. COUNT(DISTINCT ft.bill_no) fonksiyonu ile hesaplanır. Her misafir için farklı fatura sayısı. Genellikle 1 olur, ancak birden fazla fatura varsa daha yüksek olabilir.",
      "nullable": false,
      "example_values": [1, 2, 3]
    },
    {
      "column_name": "CITIZEN_NUMBER",
      "data_type": "VARCHAR2",
      "description": "Vatandaş numarası (TC kimlik no). name tablosundaki udfn30 alanından alınır, ancak sadece name_type = ''D'' (INDIVIDUAL) olan misafirler için doldurulur. Türk vatandaşları için TC kimlik numarası. Vergi bildirimleri için kullanılır. Grup veya kaynak misafirler için boş string ('''') döner.",
      "nullable": true,
      "example_values": [null, "", "16658382504"]
    },
    {
      "column_name": "TAX_NO",
      "data_type": "VARCHAR2",
      "description": "Vergi numarası. name tablosundaki tax2_no alanından alınır, ancak sadece name_type != ''D'' (Grup veya Kaynak) olan misafirler için doldurulur. Kurumsal misafirler için vergi numarası. Vergi bildirimleri için kullanılır. Bireysel misafirler için boş string ('''') döner.",
      "nullable": true,
      "example_values": [null, "", "1234567890"]
    },
    {
      "column_name": "TAX_OFFICE",
      "data_type": "VARCHAR2",
      "description": "Vergi dairesi. name tablosundaki tax1_no alanından alınır, ancak sadece name_type != ''D'' (Grup veya Kaynak) olan misafirler için doldurulur. Kurumsal misafirler için bağlı oldukları vergi dairesi. Vergi bildirimleri için kullanılır. Bireysel misafirler için boş string ('''') döner.",
      "nullable": true,
      "example_values": [null, "", "Kadıköy", "Şişli"]
    },
    {
      "column_name": "AR_NO",
      "data_type": "VARCHAR2",
      "description": "Alacak hesabı numarası. ar_tran_view_ref.get_account_number(ft.name_id) fonksiyonu ile hesaplanır. Misafirin alacak hesabı numarası. Muhasebe ve alacak takibi için kullanılır.",
      "nullable": true,
      "example_values": [null, "AR123456"]
    },
    {
      "column_name": "BILL_PAYMENT_TRX_NO",
      "data_type": "NUMBER",
      "description": "Fatura ödeme işlem numarası. folio$_tax tablosundan bill_payment_trx_no alanından alınır (ROWNUM = 1 ile ilk kayıt). Faturanın ödeme işleminin numarası. Ödeme takibi ve muhasebe işlemleri için kullanılır.",
      "nullable": true,
      "example_values": [440101, 6131409, 8845279]
    },
    {
      "column_name": "ARRIVAL",
      "data_type": "DATE",
      "description": "Geliş tarihi ve saati. reservation_name tablosundaki begin_date alanından alınır. Misafirin otele geliş tarihi ve saati. Konaklama süresi hesaplamaları ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["2012-02-12 16:49:00", "2016-05-06 17:13:00", "2019-02-24 14:50:00"]
    },
    {
      "column_name": "DEPARTURE",
      "data_type": "DATE",
      "description": "Ayrılış tarihi ve saati. reservation_name tablosundaki end_date alanından alınır. Misafirin otelden ayrılış tarihi ve saati. Konaklama süresi hesaplamaları ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["2012-02-14 06:13:00", "2016-05-08 13:53:00", "2019-02-25 12:53:00"]
    },
    {
      "column_name": "NET",
      "data_type": "NUMBER",
      "description": "Net gelir. SUM(NVL(revenue_amt, 0)) fonksiyonu ile hesaplanır. Vergi ve indirimler düşüldükten sonraki net gelir tutarı. financial_transactions_view tablosundaki revenue_amt alanlarının toplamı. Gelir analizi ve muhasebe için kritik bilgidir.",
      "nullable": true,
      "example_values": [27.966101694916, 185.185185185184, 185.185185185185]
    },
    {
      "column_name": "GROSS",
      "data_type": "NUMBER",
      "description": "Brüt gelir. SUM(NVL(guest_account_debit, 0)) fonksiyonu ile hesaplanır. Vergi ve indirimler düşülmeden önceki brüt gelir tutarı. financial_transactions_view tablosundaki guest_account_debit alanlarının toplamı. Gelir analizi ve muhasebe için kritik bilgidir.",
      "nullable": true,
      "example_values": [33, 200, 250]
    }
  ],
  "usage_scenarios": [
    "Finansal raporlama ve gelir analizi",
    "Fatura yönetimi ve takibi",
    "Vergi bildirimleri ve raporlaması",
    "Ödeme yapan kişi takibi",
    "Muhasebe işlemleri ve kayıt tutma",
    "Net ve brüt gelir hesaplamaları",
    "Kurumsal ve bireysel misafir ayrımı",
    "Vergi numarası ve vergi dairesi bilgilerine erişim",
    "Folyo yönetimi ve hesap takibi",
    "Fatura durumu takibi"
  ],
  "source_information": "Bu view, financial_transactions_view, name ve reservation_name tablolarından veri çeker. ft.name_id = n.name_id AND ft.resort = rn.resort AND ft.resv_name_id = rn.resv_name_id koşulları ile birleştirilir. bill_no IS NOT NULL koşulu ile filtrelenir. GROUP BY ile misafir, fatura, folyo ve rezervasyon bazlı gruplandırılır. Net ve gross değerleri SUM fonksiyonları ile toplanır. Ödeme yapan kişi bilgileri folio$_tax tablosundan ROWNUM = 1 ile ilk kayıt olarak alınır."
}
