        (8, 1, 'PV_ISV_HISTORY_AND_FORECAST.json', '{
  "view_name": "PV_ISV_HISTORY_AND_FORECAST",
  "description": "Geçmiş ve tahmin verileri view''ı. Bu view, otel operasyonlarının geçmiş performansını ve gelecek tahminlerini içerir. pv_res_statistics_forecast ve pv_isv_name tablolarından veri çekerek günlük bazlı detaylı istatistikler sağlar. Oda kullanımı, gelir türleri (oda, yemek, ekstra, diğer, paket), geliş/ayrılış bilgileri, complimentary ve house-use bilgileri gibi kritik operasyonel metrikleri barındırır. ADR (Average Daily Rate) hesaplamaları için TOTAL_REVENUE ve NO_ROOMS kullanılır. owner_rental_flag = ''O'' olan kayıtlar için tüm değerler 0 olarak döner. PROISV sistemi için özel olarak oluşturulmuştur.",
  "purpose": "Bu view, otel yönetim sisteminde geçmiş performans analizi, gelecek tahminleri, gelir analizi, oda kullanım istatistikleri ve raporlama için kullanılır. P2102 History And Forecast, P2532 Production(ACS) By Monthly, P2533 Production(ACS) By Yearly gibi raporların veri kaynağıdır. Yöneticiler ve analistler tarafından trend analizi, gelir optimizasyonu, kapasite planlaması ve performans takibi için kullanılır.",
  "data_types": [
    "Temel bilgiler (resort, considered_date, rec_type, name_type, account_name, account_type)",
    "Demografik bilgiler (nationality, country)",
    "Oda kullanım bilgileri (no_rooms, ind_rooms, grp_rooms, no_persons, adults, children)",
    "Geliş/ayrılış bilgileri (arrival_rooms, arrival_persons, departure_rooms, departure_persons)",
    "Özel kullanım bilgileri (day_use_rooms, day_use_persons, complimentary_rooms, complimentary_persons, house_use_rooms, house_use_persons)",
    "Gelir türleri (net_room_revenue, net_food_revenue, net_extra_revenue, net_other_revenue, total_package_revenue, total_revenue)",
    "Vergi bilgileri (room_revenue_tax, food_revenue_tax, other_revenue_tax, total_revenue_tax)",
    "Diğer gelir bilgileri (extra_revenue, non_revenue, non_revenue_tax)",
    "Bayrak alanları (complimentary_yn, house_use_yn, pm_yn, inquiry_yn, group_yn, owner_rental_flag)"
  ],
  "columns": [
    {
      "column_name": "RESORT",
      "data_type": "VARCHAR2",
      "description": "Resort/otel kodu. pv_res_statistics_forecast tablosundan alınır. Otel zincirindeki belirli bir otel veya resort''u tanımlayan kod. Örnek: ISTAL (Istanbul Altunizade). Rezervasyon ve gelir yönetimi için kullanılır.",
      "nullable": true,
      "example_values": ["ISTAL", "ISTAN", "ISTPH", "IST", "BOP"]
    },
    {
      "column_name": "CONSIDERED_DATE",
      "data_type": "DATE",
      "description": "İşlem tarihi. pv_res_statistics_forecast tablosundaki considered_date alanından alınır. İstatistiklerin hesaplandığı veya tahmin edildiği tarih. Geçmiş veriler için gerçek tarih, tahminler için gelecek tarih olabilir. Tarih bazlı filtreleme ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["2011-08-06", "2026-01-13", "2026-01-14"]
    },
    {
      "column_name": "REC_TYPE",
      "data_type": "VARCHAR2",
      "description": "Kayıt tipi. pv_res_statistics_forecast tablosundaki rec_type alanından alınır. Kaydın geçmiş (history) veya tahmin (forecast) olduğunu belirtir. Örnek: ''A_STAT'' (Actual Statistics - Gerçek İstatistikler), ''F_STAT'' (Forecast Statistics - Tahmin İstatistikleri). Veri türü ayrımı için kullanılır.",
      "nullable": true,
      "example_values": ["A_STAT", "F_STAT"]
    },
    {
      "column_name": "NAME_TYPE",
      "data_type": "VARCHAR2",
      "description": "Hesap tipi. pv_isv_name tablosundaki name_type alanından alınır. Hesabın tipini belirtir. Örnek: ''D'' (Bireysel), ''G'' (Grup), ''S'' (Kaynak), ''COMPANY'' (Şirket), ''TRAVEL_AGENT'' (Seyahat Acentesi). Hesap kategorizasyonu için kullanılır.",
      "nullable": true,
      "example_values": ["D", "G", "S", "COMPANY", "TRAVEL_AGENT"]
    },
    {
      "column_name": "NAME_TYPE_DESC",
      "data_type": "VARCHAR2",
      "description": "Hesap tipi açıklaması. name_type alanından dönüştürülür: ''S'' -> ''SOURCE'', ''D'' -> ''INDIVIDUALS'', diğerleri olduğu gibi kalır. Hesap tipinin okunabilir açıklaması. Raporlama ve görselleştirme için kullanılır.",
      "nullable": true,
      "example_values": ["INDIVIDUALS", "SOURCE", "COMPANY", "GROUP"]
    },
    {
      "column_name": "ACCOUNT_NAME",
      "data_type": "VARCHAR2",
      "description": "Hesap adı. reservation_ref.get_name fonksiyonu ile COALESCE(rsf.agent_id, rsf.company_id, rsf.GROUP_ID, rsf.source_id) değerinden hesaplanır. Eğer tüm ID''ler NULL ise ''TOTAL INDIVIDUALS'' döner. Hesabın adı (seyahat acentesi, şirket, grup, kaynak veya toplam bireysel). Hesap bazlı analiz için kullanılır.",
      "nullable": true,
      "example_values": ["TOTAL INDIVIDUALS", "Denteuropa Saglık Hiz.veTic.AS", "ABC Travel Agency"]
    },
    {
      "column_name": "ACCOUNT_TYPE",
      "data_type": "VARCHAR2",
      "description": "Hesap tipi kodu. CASE WHEN yapısı ile hesaplanır: agent_id IS NOT NULL -> ''T'' (Travel Agent), company_id IS NOT NULL -> ''C'' (Company), GROUP_ID IS NOT NULL -> ''G'' (Group), source_id IS NOT NULL -> ''S'' (Source), diğerleri -> ''Z'' (Individual/Total). Hesap tipinin kısa kodu. Filtreleme ve gruplandırma için kullanılır.",
      "nullable": true,
      "example_values": ["T", "C", "G", "S", "Z"]
    },
    {
      "column_name": "NATIONALITY",
      "data_type": "VARCHAR2",
      "description": "Uyruk. get_nationality_name(rsf.nationality) fonksiyonu ile hesaplanır. Misafirlerin uyruğu (vatandaşlığı). Örnek: ''France'', ''Turkey'', ''United States''. Demografik analiz ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": [null, "France", "Turkey", "United States"]
    },
    {
      "column_name": "COUNTRY",
      "data_type": "VARCHAR2",
      "description": "Ülke. get_country_name(rsf.country) fonksiyonu ile hesaplanır. Misafirlerin ikamet ettiği ülke. Örnek: ''Turkey'', ''France'', ''United States''. Demografik analiz ve raporlama için kullanılır.",
      "nullable": true,
      "example_values": ["Turkey", "France", "United States"]
    },
    {
      "column_name": "NO_ROOMS",
      "data_type": "NUMBER",
      "description": "Toplam oda sayısı. pv_res_statistics_forecast tablosundaki no_rooms alanından alınır, ancak owner_rental_flag = ''O'' ise 0 döner. Belirli bir tarihte kullanılan toplam oda sayısı. ADR (Average Daily Rate) hesaplamaları için kullanılır. ADR = TOTAL_REVENUE / NO_ROOMS formülü ile hesaplanır.",
      "nullable": true,
      "example_values": [0, 1, 5, 10, 50]
    },
    {
      "column_name": "IND_ROOMS",
      "data_type": "NUMBER",
      "description": "Bireysel oda sayısı. pv_res_statistics_forecast tablosundaki no_rooms alanından alınır, ancak owner_rental_flag = ''O'' ise 0 döner ve group_yn = ''N'' ise no_rooms, değilse 0 döner. Bireysel misafirler tarafından kullanılan oda sayısı. Bireysel ve grup ayrımı için kullanılır.",
      "nullable": true,
      "example_values": [0, 1, 3, 5]
    },
    {
      "column_name": "GRP_ROOMS",
      "data_type": "NUMBER",
      "description": "Grup oda sayısı. pv_res_statistics_forecast tablosundaki no_rooms alanından alınır, ancak owner_rental_flag = ''O'' ise 0 döner ve group_yn = ''Y'' ise no_rooms, değilse 0 döner. Grup misafirler tarafından kullanılan oda sayısı. Bireysel ve grup ayrımı için kullanılır.",
      "nullable": true,
      "example_values": [0, 2, 5, 10]
    },
    {
      "column_name": "NO_PERSONS",
      "data_type": "NUMBER",
      "description": "Toplam kişi sayısı. pv_res_statistics_forecast tablosundaki no_persons alanından alınır, ancak owner_rental_flag = ''O'' ise 0 döner. Belirli bir tarihte konaklayan toplam kişi sayısı. Kapasite ve doluluk analizi için kullanılır.",
      "nullable": true,
      "example_values": [0, 2, 5, 10, 50]
    },
    {
      "column_name": "ADULTS",
      "data_type": "NUMBER",
      "description": "Yetişkin sayısı. pv_res_statistics_forecast tablosundaki adults alanından alınır, ancak owner_rental_flag = ''O'' ise 0 döner. Belirli bir tarihte konaklayan yetişkin sayısı. Demografik analiz için kullanılır.",
      "nullable": true,
      "example_values": [0, 2, 4, 10]
    },
    {
      "column_name": "CHILDREN",
