  "usage_scenarios": [
    "Geçmiş performans analizi ve trend analizi",
    "Gelecek tahminleri ve planlama",
    "ADR (Average Daily Rate) hesaplamaları (TOTAL_REVENUE / NO_ROOMS)",
    "Gelir analizi (oda, yemek, ekstra, diğer, paket)",
    "Oda kullanım istatistikleri (bireysel, grup, toplam)",
    "Geliş/ayrılış takibi ve operasyonel planlama",
    "Ücretsiz (complimentary) ve ev kullanımı (house-use) analizi",
    "Günlük kullanım (day-use) analizi",
    "Vergi raporlaması ve muhasebe",
    "Hesap bazlı analiz (seyahat acentesi, şirket, grup, kaynak)",
    "Demografik analiz (uyruk, ülke)",
    "P2102 History And Forecast raporu",
    "P2532 Production(ACS) By Monthly raporu",
    "P2533 Production(ACS) By Yearly raporu"
  ],
  "source_information": "Bu view, pv_res_statistics_forecast ve pv_isv_name tablolarından veri çeker. n.name_id = COALESCE(rsf.agent_id, rsf.company_id, rsf.GROUP_ID, rsf.source_id, rsf.name_id) koşulu ile name tablosu birleştirilir. n.name_type IN (''TRAVEL_AGENT'', ''COMPANY'', ''S'', ''D'', ''G'') filtresi uygulanır. rsf.deduct_yn = ''Y'' ve rsf.inquiry_yn = ''N'' filtreleri uygulanır. owner_rental_flag = ''O'' olan kayıtlar için tüm sayısal değerler (oda, kişi, gelir) CASE WHEN yapıları ile 0 olarak döner. COMPLIMENTARY_YN ve HOUSE_USE_YN değerleri rate_header tablosundan rate_code ile eşleştirilerek alınır."
}
