        (9, 1, 'PV_ISV_MANAGER_FLASH_LY_TO_DAY.json', '{
  "view_name": "PV_ISV_MANAGER_FLASH_LY_TO_DAY",
  "description": "Yönetici flash raporu - geçen yıl (Last Year - LY) verileri view''ı. Bu view, geçen yılın aynı dönemine ait operasyonel ve finansal metrikleri sağlar. rep_manager tablosundan veri çekerek iş gününden 1 yıl öncesine kadar olan verileri toplar. Her metrik için 3 zaman dilimi sağlar: TD (Today/Day - geçen yılın bugünü), MTD (Month To Date - geçen yılın ay başından bugüne kadar), YTD (Year To Date - geçen yılın yıl başından bugüne kadar). Oda kullanımı, doluluk oranları, ADR, RevPAR, gelir türleri gibi kritik operasyonel metrikleri içerir. Tüm gelir değerleri EUR''ye çevrilir (multi_currency.get_exchange_rate fonksiyonu ile).",
  "purpose": "Bu view, otel yönetim sisteminde yönetici flash raporları için kullanılır. Geçen yılın aynı dönemi ile karşılaştırma yaparak performans analizi, trend takibi ve hedef belirleme için kritik bilgiler sunar. Yöneticiler tarafından günlük, aylık ve yıllık bazlı karşılaştırmalı analizler için kullanılır. Bu yılın performansını geçen yılın performansı ile karşılaştırmak için kullanılır.",
  "data_types": [
    "Oda envanteri metrikleri (total rooms, avail rooms, OOO rooms, OOS rooms, rooms occupied)",
    "Doluluk metrikleri (occupancy %, guest in house)",
    "Performans metrikleri (ADR, RevPAR)",
    "Rezervasyon metrikleri (no shows, cancel rooms)",
    "Özel kullanım metrikleri (comp rooms, house use rooms)",
    "Gelir metrikleri (room revenue, FB revenue, other revenue, total revenue)"
  ],
  "columns": [
    {
      "column_name": "DEFINITION",
      "data_type": "VARCHAR2",
      "description": "Metrik tanımı. Her satır bir metrik türünü temsil eder. 17 farklı metrik tanımı vardır: ''Total Rooms'' (Toplam oda sayısı), ''Avail Rooms'' (Müsait oda sayısı), ''OOO Rooms'' (Out of Order - Kullanılamaz oda sayısı), ''OOS Rooms'' (Out of Service - Hizmet dışı oda sayısı), ''Rooms Occupied'' (Dolu oda sayısı), ''Guest In House'' (Evdeki misafir sayısı), ''Occupancy %'' (Doluluk oranı - yüzde), ''ADR'' (Average Daily Rate - Ortalama günlük oda fiyatı), ''RevPar'' (Revenue Per Available Room - Müsait oda başına gelir), ''No Shows'' (Gelmeyen misafir oda sayısı), ''Cancel Rooms'' (İptal edilen oda sayısı), ''Comp Rooms'' (Complimentary - Ücretsiz oda sayısı), ''Huse Rooms'' (House Use - Ev kullanımı oda sayısı), ''Room Revenue'' (Oda geliri), ''FB Revenue'' (Food & Beverage - Yemek ve içecek geliri), ''Other Revenue'' (Diğer gelir), ''Total Revenue'' (Toplam gelir).",
      "nullable": false,
      "example_values": ["Total Rooms", "Avail Rooms", "OOO Rooms", "Rooms Occupied", "ADR", "RevPar", "Room Revenue"]
    },
    {
      "column_name": "TD",
      "data_type": "NUMBER",
      "description": "Today/Day değeri - Geçen yılın bugünü. Geçen yılın iş gününden 1 yıl öncesindeki aynı güne ait metrik değeri. ADD_MONTHS(ppf.bdate(resort) - 1, -12) tarihindeki değer. TRUNC(..., 4) fonksiyonu ile 4 ondalık basamağa yuvarlanmıştır. Günlük karşılaştırma için kullanılır.",
      "nullable": true,
      "example_values": [76, 35, 41, 53.9473, 64.6967, 34.9022, 2652.5678]
    },
    {
      "column_name": "MTD",
      "data_type": "NUMBER",
      "description": "Month To Date değeri - Geçen yılın ay başından bugüne. Geçen yılın aynı ayının başından (TRUNC(ADD_MONTHS(ppf.bdate(resort) - 1, -12), ''MONTH'')) bugüne (ADD_MONTHS(ppf.bdate(resort) - 1, -12)) kadar olan dönemdeki metrik değerlerinin toplamı. TRUNC(..., 4) fonksiyonu ile 4 ondalık basamağa yuvarlanmıştır. Aylık karşılaştırma için kullanılır.",
      "nullable": true,
      "example_values": [912, 302, 610, 66.8859, 66.8128, 44.6884, 40755.8339]
    },
    {
      "column_name": "YTD",
      "data_type": "NUMBER",
      "description": "Year To Date değeri - Geçen yılın yıl başından bugüne. Geçen yılın yıl başından (TRUNC(ADD_MONTHS(ppf.bdate(resort) - 1, -12), ''YEAR'')) bugüne (ADD_MONTHS(ppf.bdate(resort) - 1, -12)) kadar olan dönemdeki metrik değerlerinin toplamı. TRUNC(..., 4) fonksiyonu ile 4 ondalık basamağa yuvarlanmıştır. Yıllık karşılaştırma için kullanılır.",
      "nullable": true,
      "example_values": [912, 302, 610, 66.8859, 66.8128, 44.6884, 40755.8339]
    },
    {
      "column_name": "RESORT",
      "data_type": "VARCHAR2",
      "description": "Resort/otel kodu. rep_manager tablosundan alınır. Otel zincirindeki belirli bir otel veya resort''u tanımlayan kod. Örnek: ISTAL (Istanbul Altunizade). Rezervasyon ve gelir yönetimi için kullanılır.",
      "nullable": true,
      "example_values": ["ISTAL", "ISTAN", "ISTPH", "IST", "BOP"]
    }
  ],
  "metric_definitions": {
    "Total Rooms": "Toplam fiziksel oda sayısı. rep_manager tablosundaki physical_room alanının toplamı. Otelin toplam oda kapasitesini gösterir.",
    "Avail Rooms": "Müsait oda sayısı. rep_manager tablosundaki avail_room alanının toplamı. Kullanılabilir toplam oda sayısı.",
    "OOO Rooms": "Out of Order (Kullanılamaz) oda sayısı. rep_manager tablosundaki ooo_rooms alanının toplamı. Bakım, onarım veya diğer nedenlerle kullanılamayan oda sayısı.",
    "OOS Rooms": "Out of Service (Hizmet dışı) oda sayısı. rep_manager tablosundaki os_rooms alanının toplamı. Hizmet dışı bırakılan oda sayısı.",
    "Rooms Occupied": "Dolu oda sayısı. rep_manager tablosundaki occ_room alanının toplamı. Belirli bir tarihte dolu olan oda sayısı.",
    "Guest In House": "Evdeki misafir sayısı. rep_manager tablosundaki guest_in_house alanının toplamı. Belirli bir tarihte otelde konaklayan toplam misafir sayısı.",
    "Occupancy %": "Doluluk oranı (yüzde). 100 * (occ_room / physical_room) formülü ile hesaplanır. Eğer physical_room = 0 ise 0 döner. Doluluk analizi için kritik metrik.",
    "ADR": "Average Daily Rate (Ortalama günlük oda fiyatı). room_revenue / occ_room formülü ile hesaplanır. Eğer occ_room = 0 ise 0 döner. Oda geliri, dolu oda sayısına bölünerek hesaplanır. Gelir optimizasyonu için kritik metrik.",
    "RevPar": "Revenue Per Available Room (Müsait oda başına gelir). room_revenue / physical_room formülü ile hesaplanır. Eğer physical_room = 0 ise 0 döner. Oda geliri, toplam fiziksel oda sayısına bölünerek hesaplanır. Performans analizi için kritik metrik. NOT: Bu view için RevPAR hesaplaması room_revenue / physical_room formülünü kullanır.",
    "No Shows": "Gelmeyen misafir oda sayısı. rep_manager tablosundaki noshow_room alanının toplamı. Rezervasyon yapmış ancak gelmemiş misafirlerin oda sayısı.",
    "Cancel Rooms": "İptal edilen oda sayısı. rep_manager tablosundaki cancel_rooms alanının toplamı. İptal edilen rezervasyonların oda sayısı.",
    "Comp Rooms": "Complimentary (Ücretsiz) oda sayısı. rep_manager tablosundaki comp_room alanının toplamı. Ücretsiz olarak verilen oda sayısı.",
    "Huse Rooms": "House Use (Ev kullanımı) oda sayısı. rep_manager tablosundaki house_use_room alanının toplamı. Otel personeli veya yönetim tarafından kullanılan oda sayısı.",
    "Room Revenue": "Oda geliri. rep_manager tablosundaki room_revenue * curr alanının toplamı. curr, multi_currency.get_exchange_rate fonksiyonu ile EUR''ye çevrilmiş döviz kuru. Belirli bir dönemde elde edilen oda geliri (EUR cinsinden).",
    "FB Revenue": "Food & Beverage (Yemek ve içecek) geliri. rep_manager tablosundaki food_bev_revenue * curr alanının toplamı. curr, multi_currency.get_exchange_rate fonksiyonu ile EUR''ye çevrilmiş döviz kuru. Belirli bir dönemde elde edilen yemek ve içecek geliri (EUR cinsinden).",
    "Other Revenue": "Diğer gelir. rep_manager tablosundaki other_revenue * curr alanının toplamı. curr, multi_currency.get_exchange_rate fonksiyonu ile EUR''ye çevrilmiş döviz kuru. Belirli bir dönemde elde edilen diğer gelir (oda ve yemek dışındaki gelirler, EUR cinsinden).",
    "Total Revenue": "Toplam gelir. rep_manager tablosundaki total_revenue * curr alanının toplamı. curr, multi_currency.get_exchange_rate fonksiyonu ile EUR''ye çevrilmiş döviz kuru. Belirli bir dönemde elde edilen toplam gelir (tüm gelir türlerinin toplamı, EUR cinsinden)."
  },
  "usage_scenarios": [
    "Yönetici flash raporları",
    "Geçen yıl ile bu yıl karşılaştırması",
