      "usage_scenarios": [
        "Otel kontrol paneli ve dashboard görünümleri",
        "Aylık günlük bazlı oda envanteri takibi",
        "Rezervasyon planlaması ve kapasite yönetimi",
        "Doluluk oranı analizi ve tahminleme",
